#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
sort(a.begin(),a.end());
long long ops=0;
for(int i=1;i<n;++i)if(a[i]<=a[i-1]){ops+=a[i-1]+1-a[i];a[i]=a[i-1]+1;}
printf("%lld\n",ops);return 0;}

